<script setup>
import {onMounted,reactive,ref} from 'vue';import {useRouter} from 'vue-router';import api from '../../../services/api';import FormErrors from '../../../components/ui/FormErrors.vue';
const router=useRouter(),plans=ref([]),busy=ref(false),error=ref(null);const form=reactive({name:'',slug:'',timezone:'Africa/Nairobi',owner_name:'',owner_email:'',owner_password:'',owner_password_confirmation:'',plan_id:''});
onMounted(async()=>{try{plans.value=(await api.get('/v1/platform/plans')).data.data}catch(e){error.value=e}});
async function submit(){busy.value=true;error.value=null;try{const id=(await api.post('/v1/platform/tenants',form)).data.data.id;await router.replace({name:'admin.clinics.show',params:{id},query:{created:'1'}})}catch(e){error.value=e}finally{form.owner_password='';form.owner_password_confirmation='';busy.value=false}}
</script><template><div><header class="page-header"><div><RouterLink class="back-link" :to="{name:'admin.clinics'}">← Back to Clinics</RouterLink><h1 class="mt-3">Add New Clinic</h1><p>Create a new clinic organization and its owner account.</p></div></header><FormErrors :error="error"/><form class="space-y-6" @submit.prevent="submit"><section class="admin-card"><h2 class="form-section-title">1. Clinic Information</h2><div class="form-grid"><label class="field">Clinic name<input v-model="form.name" required maxlength="150"></label><label class="field">Unique clinic code<input v-model="form.slug" required pattern="[A-Za-z0-9_-]+" maxlength="80"></label><label class="field">Timezone<input v-model="form.timezone" required></label></div></section><section class="admin-card"><h2 class="form-section-title">2. Owner Account</h2><div class="form-grid"><label class="field">Owner name<input v-model="form.owner_name" required></label><label class="field">Owner email<input v-model="form.owner_email" type="email" required></label><label class="field">Password<input v-model="form.owner_password" type="password" minlength="12" autocomplete="new-password" required><span class="hint">12+ characters with mixed case and a number.</span></label><label class="field">Confirm password<input v-model="form.owner_password_confirmation" type="password" autocomplete="new-password" required></label></div></section><section class="admin-card"><h2 class="form-section-title">3. Subscription</h2><div class="form-grid"><label class="field">Plan<select v-model="form.plan_id" required><option disabled value="">Select a plan</option><option v-for="item in plans" :key="item.id" :value="item.id">{{item.name}} · {{item.trial_days}} trial days</option></select></label><div><p class="field">Initial status</p><p class="mt-2 text-sm text-slate-600">Trial — set from the selected plan.</p></div></div></section><section class="admin-card"><h2 class="form-section-title">4. Initial Branch</h2><p class="text-sm text-slate-600">A branch named “Main branch” will be created automatically.</p></section><div class="sticky-actions"><RouterLink class="btn-secondary" :to="{name:'admin.clinics'}">Cancel</RouterLink><button class="btn" :disabled="busy">{{busy?'Creating…':'Create Clinic'}}</button></div></form></div></template>
